using Finora.Application;using Finora.Domain;namespace Finora.App;public sealed class SettingsViewModel:ViewModelBase{private readonly IAppSettingsService _settings;private bool _privacyMode,_hideAmounts,_reducedMotion,_backupReminders,_localPremiumDemoEnabled;private ThemePreference _theme;private string _currency;private int _monthStartDay,_autoLockMinutes;public SettingsViewModel(IAppSettingsService settings){_settings=settings;_privacyMode=settings.PrivacyMode;_hideAmounts=settings.HideAmountsOnLaunch;_reducedMotion=settings.ReducedMotion;_backupReminders=settings.BackupRemindersEnabled;_theme=settings.Theme;_currency=settings.DefaultCurrency;_monthStartDay=settings.FinancialMonthStartDay;_autoLockMinutes=settings.AutoLockMinutes;_localPremiumDemoEnabled=settings.LocalPremiumDemoEnabled;}public IReadOnlyList<ThemePreference> Themes{get;}=Enum.GetValues<ThemePreference>();public bool PrivacyMode{get=>_privacyMode;set{if(SetProperty(ref _privacyMode,value))_settings.PrivacyMode=value;}}public bool HideAmounts{get=>_hideAmounts;set{if(SetProperty(ref _hideAmounts,value))_settings.HideAmountsOnLaunch=value;}}public bool ReducedMotion{get=>_reducedMotion;set{if(SetProperty(ref _reducedMotion,value))_settings.ReducedMotion=value;}}public bool BackupReminders{get=>_backupReminders;set{if(SetProperty(ref _backupReminders,value))_settings.BackupRemindersEnabled=value;}}public ThemePreference Theme{get=>_theme;set{if(SetProperty(ref _theme,value)){_settings.Theme=value;ApplyTheme(value);}}}public string Currency{get=>_currency;set{var n=(value??"").Trim().ToUpperInvariant();if(n.Length is >=3 and <=8&&SetProperty(ref _currency,n))_settings.DefaultCurrency=n;}}public int MonthStartDay{get=>_monthStartDay;set{var n=Math.Clamp(value,1,28);if(SetProperty(ref _monthStartDay,n))_settings.FinancialMonthStartDay=n;}}public int AutoLockMinutes{get=>_autoLockMinutes;set{var n=Math.Clamp(value,1,60);if(SetProperty(ref _autoLockMinutes,n))_settings.AutoLockMinutes=n;}}public bool LocalPremiumDemoEnabled{get=>_localPremiumDemoEnabled;set{if(SetProperty(ref _localPremiumDemoEnabled,value))_settings.LocalPremiumDemoEnabled=value;}}public static void ApplyTheme(ThemePreference theme){if(Application.Current is null)return;Application.Current.UserAppTheme=theme switch{ThemePreference.Light=>AppTheme.Light,ThemePreference.Dark=>AppTheme.Dark,_=>AppTheme.Unspecified};}}
